CREATE PROCEDURE wave_diff___TOKEN__(later integer, earlier integer, INOUT acc integer)
LANGUAGE plpgsql
AS $$
BEGIN
  acc := acc + later - earlier;
END
$$;
CREATE FUNCTION wave_rows___TOKEN__(n integer) RETURNS TABLE(k integer, sq integer)
LANGUAGE sql
AS $$ SELECT g, g * g FROM generate_series(1, n) AS g ORDER BY g $$;
CREATE FUNCTION wave_fout___TOKEN__(n integer, OUT twice integer, OUT label text)
LANGUAGE sql
AS $$ SELECT n * 2, 'f' || n $$;

CREATE PROCEDURE wave_diff___TOKEN__(later IN NUMBER, earlier IN NUMBER, acc IN OUT NUMBER)
AS
BEGIN
  acc := acc + later - earlier;
END;
/
CREATE PROCEDURE wave_rows___TOKEN__(n IN NUMBER)
AS
  c SYS_REFCURSOR;
BEGIN
  OPEN c FOR SELECT level AS "k", level * level AS "sq" FROM dual CONNECT BY level <= n ORDER BY level;
  DBMS_SQL.RETURN_RESULT(c);
END;
/

CREATE PROCEDURE dbo.wave_diff___TOKEN__ @later int, @earlier int, @acc int OUTPUT
AS
BEGIN
  SET @acc = @acc + @later - @earlier;
END;
GO
CREATE PROCEDURE dbo.wave_rows___TOKEN__ @n int
AS
BEGIN
  SELECT value AS k, value * value AS sq FROM GENERATE_SERIES(1, @n) ORDER BY value;
END;

DROP PROCEDURE IF EXISTS wave_diff___TOKEN__;
DROP FUNCTION IF EXISTS wave_rows___TOKEN__;
DROP FUNCTION IF EXISTS wave_fout___TOKEN__;
